import { useOptimistic, useState } from "react";

export default function Todo() {
  const [items, setItems] = useState(["Read docs"]);
  const [optimisticItems, removeOptimistic] = useOptimistic(
    items,
    (current, item) => current.filter((value) => value !== item)
  );

  async function remove(item) {
    removeOptimistic(item);
    await new Promise((resolve, reject) =>
      setTimeout(() => reject(new Error("Delete failed")), 500)
    );
    setItems((current) => current.filter((value) => value !== item));
  }

  return (
    <button onClick={() => remove("Read docs")}>
      {optimisticItems.join(", ") || "Empty"}
    </button>
  );
}

