export default function CatList({ cats }: { cats: string[] }) {
  const [nodes, setNodes] = useState(new Map<string, HTMLLIElement>());

  return (
    <ul>
      {cats.map((cat) => (
        <li
          key={cat}
          ref={(node) => {
            if (node) {
              setNodes((current) => new Map(current).set(cat, node));
            } else {
              setNodes((current) => {
                const next = new Map(current);
                next.delete(cat);
                return next;
              });
            }
          }}
        >
          {cat}
        </li>
      ))}
    </ul>
  );
}

